 "nwrbloa4z1": "60 ml de vinagre de manzana",
 "1zgznuaftmn": "100 g de cebolla, partida a la mitad, a fuego lento",
 "194xf4fgygz": "20 g de ajo, dientes enteros, a fuego lento",
 "mz3hcemk4q": "2 hojas de laurel",
